splayName;const BI=cu("inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",{variants:{variant:{default:"bg-primary text-primary-foreground hover:bg-primary/90",destructive:"bg-destructive text-destructive-foreground hover:bg-destructive/90",outline:"border border-input bg-background hover:bg-accent hover:text-accent-foreground",secondary:"bg-secondary text-secondary-foreground hover:bg-secondary/80",ghost:"hover:bg-accent hover:text-accent-foreground",link:"text-primary underline-offset-4 hover:underline",hero:"bg-ink text-brand-deep font-semibold hover:bg-cream shadow-lg hover:shadow-xl hover:-translate-y-0.5",heroOutline:"border border-ink/25 text-ink bg-transparent hover:bg-ink/10 font-medium",enterprise:"bg-brand-deep text-ink font-semibold hover:bg-brand-mid shadow-md hover:shadow-lg hover:-translate-y-0.5",enterpriseOutline:"border border-brand-deep/30 text-brand-deep bg-transparent hover:bg-brand-deep hover:text-ink font-medium"},size:{default:"h-10 px-4 py-2",sm:"h-9 rounded-md px-3",lg:"h-12 rounded-md px-8 text-base",xl:"h-14 rounded-lg px-10 text-lg",icon:"h-10 w-10"}},defaultVariants:{variant:"default",size:"default"}}),Tt=w.forwardRef(({className:e,variant:t,size:n,asChild:r=!1,...i},o)=>{const a=r?IE:"button";return f.jsx(a,{className:Y(BI({variant:t,size:n,className:e})),ref:o,...i})});Tt.displayName="Button";const $e={name:"Auxilium Specialty",legalName:"Auxilium Specialty Inc.",formerName:"Axiom Specialty",dba:"Also doing business as Axiom Specialty.",tagline:"Insuring industrial revolutions.",description:"A managing general agent underwriting the risks of frontier technology, starting with AI liability.",domain:"auxiliums.com",url:"https://auxiliums.com",email:{contact:"contact@auxiliums.com",submissions:"submissions@auxiliums.com"},social:{linkedin:"https://www.linkedin.com/company/auxilium-specialty/"},external:{certify:"https://certify.auxiliums.com",govern:"https://govern.auxiliums.com"}};function eh({tone:e="dark",compact:t=!1,className:n,asLink:r=!0}){const i=e==="light"?"/brand/auxilium-wordmark-cream.png":"/brand/auxilium-wordmark-green.png",o=f.jsxs("span",{className:Y("inline-flex flex-col items-start leading-none select-none",n),children:[f.jsx("img",{src:i,alt:$e.name,width:900,height:169,className:t?"h-[1.35rem] w-auto":"h-7 w-auto",decoding:"async"}),!t&&f.jsx("span",{className:Y("font-mono text-[0.5rem] font-medium uppercase tracking-[0.315em] mt-[0.5rem] opacity-75",e==="light"?"text-ink":"text-brand-deep"),children:"Specialty Insurance"})]});return r?f.jsx(Ee,{to:"/","aria-label":`${$e.name}, home`,className:"inline-flex focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-signal rounded-sm",children:o}):o}const th=[{slug:"ai-liability",name:"AI Liability",blurb:"Standalone AI liability for the organization that runs the AI and owes the duty. Eight insuring agreements under one aggregate, five of them first-party on discovery.",status:"alpha",href:"/products/ai-liability"},{slug:"ai-liability-developers",name:"Embedded Agentic Coverage",menuName:"Embedded Agentic Risk",blurb:"Liability for the organizations that build and supply AI systems to others.",status:"development",href:"/coming-soon/ai-liability-developers",summary:"Model and application developers carry a different duty than the businesses that deploy them: what was represented, what was tested, and what the system was released to do. Auxilium is building a developer-side form for that exposure, separate from the deployer policy written today.",focus:["Representations, documentation, and release gating","Evaluation and red-team evidence at ship time","Downstream misuse and foreseeable-deployment exposure","Indemnity obligations owed to enterprise customers"],detail:[{title:"How it works",intro:"Agent developers embed our API once. From then on every deployment they ship is a placement: we read how that specific deployment is actually configured, watch it run for thirty days, and offer cover priced on what it turned out to be rather than on what the category is assumed to be.",steps:[{title:"Embed the API",body:"One integration into your platform. It registers each new customer deployment with us and opens a telemetry channel. Nothing is installed in your customer's environment beyond what your own product already runs."},{title:"We read the deployment",body:"At registration we take the structure rather than the marketing: what the agent is permitted to do, what it can reach, what caps and approvals sit around it, and where a human stays in the loop. The same facts our own underwriters ask for, arriving as data instead of a questionnaire."},{title:"Thirty days of telemetry",body:"We watch how the deployment actually behaves: what it really touches, how often it acts on its own, and how far its authority is exercised in practice. Configured authority and exercised authority are rarely the same number, and the gap is most of the risk."},{title:"Cover is offered on that deployment",body:"At the end of the window we price that specific deployment and the offer surfaces inside your product. No application, no broker submission, no waiting: the underwriting already happened while the agent was working."},{title:"It reprices as the deployment changes",body:"Authority granted later, a new system connected, a control removed: the telemetry shows it and the terms follow. Cover tracks what the agent is doing now rather than what it was doing at bind."}],note:"In development. The developer-side form is separate from the deployer policy written today, and nothing here is an offer of insurance or a commitment to quote."}]}],nh=[{slug:"warehouse-robotics",name:"Warehouse Robotics",blurb:"Liability for autonomous mobile robots and picking systems inside fulfillment operations.",status:"development",href:"/coming-soon/warehouse-robotics",summary:"Fulfillment floors now mix people, autonomous mobile robots, and picking arms at speed and density no prior general liability form was rated for. Auxilium is building coverage for what happens when that mix goes wrong.",focus:["Human and robot shared-floor bodily injury","Inventory and third-party goods damage","Fleet coordination and traffic-management failure","Telemetry-based rating across the fleet"],detail:[{title:"Coverage",intro:"Fulfillment floors run autonomous mobile robots and picking systems in the same aisles as people, at densities ISO 3691-4 and ANSI/RIA R15.08 were written to govern and that no general liability form was rated for. The cover follows the ways that mix actually fails.",coverage:[{name:"Shared-floor bodily injury",covers:"Injury to a person struck, trapped or crushed by a mobile robot or a picking system in normal operation, including visitors, contractors and agency staff on the floor.",basis:["Third party"]},{name:"Goods in your care",covers:"Damage to inventory and to third-party goods held for a customer when a robot drops, collides with or mishandles a load, including the pod or rack it was carrying.",basis:["First party","Third party"]},{name:"Fleet coordination failure",covers:"Loss when the traffic-management layer, not an individual robot, is at fault: deadlock, mis-sequencing, or two machines routed into the same space.",basis:["First party"]},{name:"Operational interruption",covers:"Lost throughput while a fleet is stood down after an event, including the cost of reverting to manual picking and the re-commissioning needed to restart.",basis:["First party"]},{name:"Unauthorized control",covers:"Physical loss following unauthorized access to the fleet management system, where a cyber policy answers the intrusion but not the damage the machines then do.",basis:["First party","Third party"]},{name:"Regulatory proceedings",covers:"Defense and investigation costs in a workplace safety proceeding arising from an event involving the fleet, within the elected scope.",basis:["Regulatory"]}],note:"Indicative cover for a line in development, not a schedule of insurance and not an offer to quote. Agreement names, triggers, sublimits and exclusions are subject to the filed wording, and the wording governs in every respect."}]},{slug:"manufacturing-autonomous-machinery",name:"Manufacturing Machinery",blurb:"Coverage for self-directed machinery on the production line.",status:"development",href:"/coming-soon/manufacturing-autonomous-machinery",summary:"When machinery makes its own decisions, failure is no longer just mechanical, it is a question of software, sensing, and judgment. Auxilium is developing coverage for the consequences of autonomous production machinery getting it wrong.",focus:["Sensor, control, and decision-logic failure","Resulting property and operational loss","Human-in-the-loop and override design","Continuous-monitoring underwriting"],detail:[{title:"Coverage",intro:"When a machine chooses its own next action, failure stops being purely mechanical. The cover is written around sensing, control and judgment, and around collaborative operation, where ISO 10218 and ISO/TS 15066 put a person inside the working envelope by design.",coverage:[{name:"Decision-logic failure",covers:"Loss where the machine did what it decided to do and the decision was wrong: mis-sensed material, a misread setpoint, or an action taken outside the intended envelope.",basis:["First party"]},{name:"Resulting product loss",covers:"Scrap, rework and the cost of quarantining and re-inspecting output produced between the failure and its discovery, which is usually the larger number.",basis:["First party"]},{name:"Collaborative operation injury",covers:"Injury to a person working inside the machine's envelope, where power and force limiting, speed and separation monitoring, or the safeguarding around them did not hold.",basis:["Third party"]},{name:"Override and stop failure",covers:"Loss where a human-in-the-loop control existed but did not arrest the process: an override ignored, a stop that did not stop, or an approval gate bypassed.",basis:["First party","Third party"]},{name:"Operational interruption",covers:"Downtime while the line is stopped, the cell is re-validated and the control configuration is re-qualified before production restarts.",basis:["First party"]},{name:"Regulatory proceedings",covers:"Defense and investigation costs in a workplace safety or machinery-directive proceeding arising from a covered event, within the elected scope.",basis:["Regulatory"]}],note:"Indicative cover for a line in development, not a schedule of insurance and not an offer to quote. Agreement names, triggers, sublimits and exclusions are subject to the filed wording, and the wording governs in every respect."}]},{slug:"delivery-robotics",name:"Delivery Robotics",blurb:"Liability for sidewalk, curbside, and aerial delivery fleets in public space.",status:"development",href:"/coming-soon/delivery-robotics",summary:"Delivery robots operate where the public is, on sidewalks, at curbs, and overhead. The exposure is third-party from the first mile. Auxilium is building coverage for the operators putting those fleets into public space.",focus:["Pedestrian and third-party bodily injury","Municipal permitting and public-right-of-way conditions","Cargo, custody, and last-mile loss","Route, density, and operational-domain rating"],detail:[{title:"Coverage",intro:"A delivery fleet works where the public is. Sidewalk and curbside robots generally sit outside auto liability and fall to general and product liability, which means the exposure is third-party from the first mile and the permit conditions are part of the risk.",coverage:[{name:"Public bodily injury",covers:"Injury to a pedestrian, cyclist or bystander struck by, tripped over or obstructed by a robot operating in public space, including at crossings and curb transitions.",basis:["Third party"]},{name:"Third-party property damage",covers:"Damage to vehicles, storefronts, street furniture and private property caused by a unit in transit or at rest.",basis:["Third party"]},{name:"Cargo and custody",covers:"Loss of or damage to the goods carried, including spoilage on a stalled unit and loss following theft or tampering while the robot is unattended.",basis:["First party"]},{name:"Right-of-way and permit conditions",covers:"Defense costs and claims arising from operation in the public right of way, including alleged breach of a municipal permit condition or operating-area restriction.",basis:["Third party","Regulatory"]},{name:"Fleet grounding",covers:"Operational loss where a regulator, a municipality or your own protocol grounds the fleet in a jurisdiction after an event.",basis:["First party"]},{name:"Unauthorized control",covers:"Physical and third-party loss following unauthorized access to a unit or to the fleet control plane, where a cyber policy answers the intrusion and not its consequences.",basis:["First party","Third party"]}],note:"Aerial delivery is not automatic cover and requires an express endorsement and specialist review. Indicative cover for a line in development, not a schedule of insurance and not an offer to quote. Agreement names, triggers, sublimits and exclusions are subject to the filed wording, and the wording governs in every respect."}]},{slug:"humanoids",name:"Humanoids",blurb:"Liability for humanoid robots in commercial and industrial settings.",status:"development",href:"/coming-soon/humanoids",summary:"Humanoid robots are moving from demos into warehouses, plants, and storefronts. Auxilium is building the liability framework for machines that share physical space with people and property.",focus:["Bodily injury and third-party property damage","Autonomy-level and operator-oversight rating","Product and operational liability blend","Fleet telemetry-based underwriting"],detail:[{title:"Coverage",intro:"A humanoid is bought to work where a person works, which means it inherits a person's proximity to people and property without inheriting a person's judgment. The cover is written for general-purpose machines operating in spaces built for humans.",coverage:[{name:"Shared-space bodily injury",covers:"Injury to an employee, customer or visitor from contact, a dropped load or a loss of balance, in premises laid out for people rather than for machines.",basis:["Third party"]},{name:"Third-party property damage",covers:"Damage to premises, fittings, stock and customer property caused by the machine moving through and handling a human environment.",basis:["Third party"]},{name:"Task execution failure",covers:"Your own loss where the machine completed the wrong task correctly: goods mishandled, a process step missed, or a general-purpose instruction carried out beyond its intent.",basis:["First party"]},{name:"Supervision and autonomy level",covers:"Loss arising where the machine operated at a higher autonomy level than scheduled, or where remote supervision was absent, delayed or ineffective.",basis:["First party","Third party"]},{name:"Unauthorized control",covers:"Physical and third-party loss following unauthorized access to the unit or its control plane, including instruction injection through its own sensing.",basis:["First party","Third party"]},{name:"Regulatory proceedings",covers:"Defense and investigation costs in a workplace safety or consumer protection proceeding arising from a covered event, within the elected scope.",basis:["Regulatory"]}],note:"Indicative cover for a line in development, not a schedule of insurance and not an offer to quote. Agreement names, triggers, sublimits and exclusions are subject to the filed wording, and the wording governs in every respect."}]},{slug:"autonomous-vehicles",name:"Autonomous Vehicles",blurb:"Liability for self-driving fleets, from robotaxis to autonomous trucking.",status:"development",href:"/coming-soon/autonomous-vehicles",summary:"As vehicles take the wheel, liability shifts from the driver to the system that drives. Auxilium is building coverage for the operators and fleets deploying autonomous vehicles on real roads.",focus:["Bodily injury and third-party property damage","Autonomy-level and operational-domain rating","Sensor, software, and decision-logic failure","Fleet telemetry-based underwriting"]}],yb=[{slug:"mgbox",name:"MGBox",blurb:"The AI-native operating platform that runs our MGA, from submission to bind.",status:"development",href:"/coming-soon/mgbox",summary:"MGBox is the AI-native platform Auxilium runs its own MGA on, from broker submission to underwriter pricing, authority, and bind. We are tenant zero: over the next few years we are hardening it into a platform other MGAs can license to become AI-native.",focus:["Broker submissions, quotes, and bind in one place","Authority-gated underwriting decisions and referrals","A product registry: new lines as a workflow, not a rebuild","Appointments, authorities, bordereau, and compliance"],detail:[{title:"From submission to bind",intro:"One path through the MGA, with the authority check built into the path rather than bolted onto it. Every step leaves a record, so what was decided and who was allowed to decide it is answerable later without reconstructing it from email.",steps:[{title:"The submission arrives",body:"An appointed broker submits once. The application and exposure schedule land as structured data, not as an attachment somebody has to retype, and the file opens with the public-record check already run."},{title:"It is priced against the ratebook",body:"The rating plan is a versioned artifact rather than a spreadsheet on somebody's desktop. Every quote records which ratebook version produced it, so a number can be explained months later."},{title:"Authority decides who answers",body:"Limits, appetite and referral triggers are configuration. Inside authority an underwriter quotes; outside it the file routes to whoever does hold that authority, with the reason attached. Nobody has to remember where the line is."},{title:"Bind, and the record closes",body:"Binding writes the policy, the schedule and the elections together. Bordereau and regulatory reporting are produced from that record rather than assembled afterwards from three systems."}],note:"MGBox is not offered publicly. We run our own MGA on it."},{title:"Why we built it",intro:"The plan is not to sell software. It is to find out whether an MGA can be run this way at all, on our own book, before anyone else has to trust it.",points:[{title:"Tenant zero",body:"We are the first and hardest user. Every gap in the platform is a gap in our own underwriting day, which is a considerably faster feedback loop than a customer filing a ticket."},{title:"A new line is a workflow, not a rebuild",body:"Products live in a registry: agreements, elections, rating inputs and authority rules as data. Launching a line is configuring one, which is what makes a small team able to carry several."},{title:"The record is the point",body:"An AI-native MGA only works if every automated step is attributable and reversible. The platform is built so that a decision, a price and an authority can each be traced back to their inputs."}]}]},{slug:"auxcontrol",name:"AuxControl",blurb:"The risk-mitigation suite every insured gets: adversarial agent testing, accreditation, and continuous governance.",status:"in-development",href:"/coming-soon/auxcontrol",summary:"AuxControl is the active side of an Auxilium policy. Rather than transferring the risk and waiting for a claim, the insured gets the tooling to find and close exposure while the policy is in force: adversarial testing of deployed agents, accreditation of the systems that pass, and continuous governance over how they run.",focus:["Adversarial testing and red-teaming of deployed agents","Accreditation for the systems that pass evaluation","Continuous governance: authority, logging, and kill switch","Findings that feed pricing and renewal terms"],detail:[{title:"See the AI running through your organization",intro:"AuxControl connects to your workspace read-only, discovers every AI model, agent and shadow tool in use, scores the exposure the way an underwriter would, and keeps watching so nothing drifts unseen. It is the loss-control half of the policy: the part that lowers the risk rather than transferring it.",points:[{title:"Discovery, including the shadow",body:"It inventories the AI actually in use, sanctioned or not, maps each tool to the people using it, and surfaces the ones nobody told you about. Most organizations are surprised by this list."},{title:"Scored like an underwriter",body:"A versioned scoring engine turns that surface into a single risk index, on the same basis your policy is underwritten. The number your broker sees and the number you see are the same number."},{title:"Watched continuously",body:"Live telemetry and scheduled syncs re-check posture, raise alerts when an agent drifts or goes silent, and produce reports a board can read. Risk is managed between renewals, not only at them."}]},{title:"How it works",steps:[{title:"Connect your workspace",body:"Your admin grants read-only access to Google Workspace or Microsoft 365. No software to deploy, no code changes, no agent to install."},{title:"We assess the surface",body:"It inventories the AI models, agents and copilots in use, maps them to your people, and flags shadow AI."},{title:"Risk is scored",body:"The scoring engine turns that surface into a collective risk index, versioned so a score can be explained later."},{title:"Monitored continuously",body:"Detection rules run around the clock against live telemetry, raising alerts on drift and producing board-ready reports."}],note:"Live in an afternoon rather than a quarter. The first sync reads your directory and AI activity within minutes."},{title:"What it reads, and what it never touches",intro:"AuxControl reads through the providers' own admin APIs. It never writes to your tenant, never opens file contents, and can be disconnected at any time.",contrast:[{title:"What it reads",items:["Directory headcount, which sizes the monitored population","AI application and model usage, which finds sanctioned and shadow AI","Admin audit events, which detect drift and silent agents"]},{title:"What it never touches",items:["File and message contents, which are never accessed","Anything written back to your tenant, because access is strictly read-only","Your environment, because there is nothing to install in it"]}]},{title:"Adversarial testing and accreditation",intro:"Monitoring tells you what an agent is doing. Testing tells you what it would do under pressure. AuxControl runs deployed agents through a certification range: live tool calls, adversarial users and poisoned documents, producing a risk profile across the dimensions of agentic liability rather than a pass or fail.",points:[{title:"A range, not a checklist",body:"Agents face simulated adversaries and hostile inputs in a live environment. What comes out is a measured profile of how the agent behaves when someone is actively trying to make it fail."},{title:"Bound to the deployment",body:"An accreditation is hash-bound to the configuration that earned it: model, scaffold, tools, guardrails and prompt. Change the thing materially and the accreditation is void, because it no longer describes what is running."},{title:"Evidence, never a condition",body:"Results inform underwriting and renewal terms. They are never a condition of cover, and accreditation is not insurance: it is evidence about a system, not a promise to pay."}],cta:{label:"Go to the certification range",href:"https://certify.auxiliums.com"}},{title:"How you get it",intro:"AuxControl is loss control attached to an Auxilium policy, not software sold on its own. Binding a policy provisions it.",points:[{title:"Included at bind",body:"Every AI Liability policyholder is provisioned AuxControl free when the policy binds. No separate purchase, and everything needed to monitor your covered exposure is in it."},{title:"Upgrade for the whole organization",body:"Policyholders who want to govern beyond the exposure their policy covers can upgrade: full workspace discovery, compliance frameworks, governance policies, scheduled reports and the audit trail."},{title:"Priced on the population",body:"The upgrade is priced on the population pulled from your directory rather than on seats, because the risk spans the whole workforce and not just the people who log in. Annual, all features included."}],cta:{label:"Go to AuxControl",href:"https://govern.auxiliums.com"},note:"In development under this name. Findings feed underwriting and renewal, and enrollment is never a condition of coverage."}]}],UI=[...th,...nh],vb=e=>[...th,...nh,...yb].find(t=>t.slug===e),ku=[{label:"Digital Risk",description:"Cover for the duty owed when AI acts.",items:th,href:"/products/ai-liability"},{label:"Robotics",description:"Liability for machines that act physically.",items:nh},{label:"Software",description:"Risk tools for the insured, and our own platform.",items:yb}].filter(e=>e.items.length>0);function Tg(e){const t=bu(),n=w.useRef(null);return w.useEffect(()=>{const r=n.current;if(!r)return;const i=o=>{o.stopPropagation(),o.preventDefault(),t(e)};return r.addEventListener("click",i,!0),()=>r.removeEventListener("click",i,!0)},[t,e]),n}var Su="Collapsible",[HI,xb]=Ur(Su),[VI,rh]=HI(Su),wb=w.forwardRef((e,t)=>{const{__scopeCollapsible:n,open:r,defaultOpen:i,disabled:o,onOpenChange:a,...s}=e,[l,u]=Or({prop:r,defaultProp:i??!1,onChange:a,caller:Su});return f.jsx(VI,{scope:n,disabled:o,contentId:Ni(),open:l,onOpenToggle:w.useCallback(()=>u(c=>!c),[u]),children:f.jsx(ne.div,{"data-state":oh(l),"data-disabled":o?"":void 0,...s,ref:t})})});wb.displayName=Su;var bb="CollapsibleTrigger",kb=w.forwa